code_sketch:
struct MonsterType: Codable {
    let id: String
    let baseHealth: Int
    let attack: String
}
struct Monster {
    let type: MonsterType
    var health: Int
    init(type: MonsterType) { self.type = type; self.health = type.baseHealth }
}
let decoded = try JSONDecoder().decode([MonsterType].self, from: data)
let registry = Dictionary(decoded.map { ($0.id, $0) }, uniquingKeysWith: { _, last in last })
